def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(tok: str) -> int | None:
        if not tok or any(c < "0" or c > "9" for c in tok):
            return None
        return int(tok)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False
        if verb == "open" and len(parts) == 3:
            a, raw = parts[1], parts[2]
            n = parse_amount(raw)
            if n is not None and a not in balances:
                balances[a] = n
                history.append(("open", a))
                ok = True
        elif verb == "deposit" and len(parts) == 3:
            a, raw = parts[1], parts[2]
            n = parse_amount(raw)
            if n is not None and n > 0 and a in balances:
                balances[a] += n
                history.append(("deposit", a, n))
                ok = True
        elif verb == "withdraw" and len(parts) == 3:
            a, raw = parts[1], parts[2]
            n = parse_amount(raw)
            if (
                n is not None
                and n > 0
                and a in balances
                and a not in frozen
                and balances[a] >= n
            ):
                balances[a] -= n
                history.append(("withdraw", a, n))
                ok = True
        elif verb == "transfer" and len(parts) == 4:
            a, b, raw = parts[1], parts[2], parts[3]
            n = parse_amount(raw)
            if (
                n is not None
                and n > 0
                and a != b
                and a in balances
                and b in balances
                and a not in frozen
                and balances[a] >= n
            ):
                balances[a] -= n
                balances[b] += n
                history.append(("transfer", a, b, n))
                ok = True
        elif verb == "freeze" and len(parts) == 2:
            a = parts[1]
            if a in balances and a not in frozen:
                frozen.add(a)
                history.append(("freeze", a))
                ok = True
        elif verb == "unfreeze" and len(parts) == 2:
            a = parts[1]
            if a in balances and a in frozen:
                frozen.discard(a)
                history.append(("unfreeze", a))
                ok = True
        elif verb == "undo" and len(parts) == 1 and history:
            rec = history.pop()
            kind = rec[0]
            if kind == "open":
                balances.pop(rec[1], None)
                frozen.discard(rec[1])
            elif kind == "deposit":
                balances[rec[1]] -= rec[2]
            elif kind == "withdraw":
                balances[rec[1]] += rec[2]
            elif kind == "transfer":
                balances[rec[1]] += rec[3]
                balances[rec[2]] -= rec[3]
            elif kind == "freeze":
                frozen.discard(rec[1])
            elif kind == "unfreeze":
                frozen.add(rec[1])
            ok = True
        if not ok:
            rejected.append(i)
    return balances, rejected
